/**
 * Ownership rules for files the docs compose stage writes (#398).
 *
 * docs/apps/<app>/guide.md and marketing.md are either GENERATED by
 * scripts/docs/compose.mjs from a source partial (_narrative.md /
 * _marketing_hook.md) or HAND-WRITTEN by an author. Compose may only ever
 * replace a file it generated itself. A generated file carries
 * GENERATED_MARKER; files composed before the marker existed are recognised by
 * the `generated:` key compose has always put in their front matter. A file
 * with neither is hand-written and compose leaves it alone.
 *
 * The `generated:` timestamp is volatile: two composes of the same sources
 * differ only there, so an unchanged file is not rewritten (no timestamp churn).
 */

export const GENERATED_MARKER =
  '<!-- AUTODOCS:GENERATED by scripts/docs/compose.mjs from the _narrative.md / _marketing_hook.md beside it. Edit that source, not this file, then run pnpm docs:compose. -->';

const FRONT_MATTER = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/;
const GENERATED_KEY = /^generated:[ \t]*\S/m;
const GENERATED_LINE = /^generated:[^\n]*\n?/m;

/** True when `content` is a file compose generated (marker or legacy front-matter key). */
export function isGenerated(content) {
  if (content.includes(GENERATED_MARKER)) return true;
  const fm = content.match(FRONT_MATTER);
  return Boolean(fm && GENERATED_KEY.test(fm[1]));
}

/** Content with line endings normalised and the volatile `generated:` line removed. */
export function stableBody(content) {
  const lf = content.replace(/\r\n?/g, '\n');
  const fm = lf.match(FRONT_MATTER);
  if (!fm) return lf;
  return (
    lf.slice(0, fm.index) + fm[0].replace(GENERATED_LINE, '') + lf.slice(fm.index + fm[0].length)
  );
}

/**
 * Decide what compose does with one output file.
 *
 * @param {object} p
 * @param {string|null} p.existing  current file content, or null when absent
 * @param {string|null} p.source    the source partial's content, or null when absent
 * @returns {'write'|'handwritten'|'no-source'} where 'write' means compose owns
 *   the file and has a source to build it from ('unchanged' is decided later by
 *   comparing stableBody of old and new).
 */
export function planOutput({ existing, source }) {
  if (existing !== null && !isGenerated(existing)) return 'handwritten';
  if (source === null) return 'no-source';
  return 'write';
}

/** True when writing `next` over `existing` would change only the timestamp (or nothing). */
export function isUnchanged(existing, next) {
  return existing !== null && stableBody(existing) === stableBody(next);
}
